import math
from itertools import combinations_with_replacement

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a*b) // gcd(a, b)

def array_gcd(arr):
    if not arr:
        return 0
    result = arr[0]
    for i in range(1, len(arr)):
        result = gcd(result, arr[i])
    return result

def array_lcm(arr):
    if not arr:
        return 1
    result = arr[0]
    for i in range(1, len(arr)):
        result = lcm(result, arr[i])
    return result

def count_good_partitions(sequence):
    n = len(sequence)
    count = 0

    # Check partitions for k = 1 to n-1
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_A = array_lcm(A_k)
        gcd_B = array_gcd(B_k)

        if lcm_A == gcd_B:
            count += 1

    return count

def search_n5():
    MAX_VAL = 20
    N = 5
    max_count = -1
    best_sequence = None

    # Iterate through all strictly increasing sequences of length 5 where elements are < 20
    # We use combinations of 5 numbers from {1, 2, ..., 19}
    candidates = list(combinations_with_replacement(range(1, MAX_VAL), N))

    # Since combinations_with_replacement gives us multisets, we must handle ordering.
    # For a sequence a1 < a2 < a3 < a4 < a5, we only care about unique increasing sequences.
    # combinations() handles strict ordering automatically if we ensure uniqueness.

    import itertools

    all_sequences = []
    for seq in itertools.combinations(range(1, MAX_VAL), N):
        all_sequences.append(list(seq))

    print(f"Total sequences to check: {len(all_sequences)}")

    for seq in all_sequences:
        count = count_good_partitions(seq)

        if count > max_count:
            max_count = count
            best_sequence = seq

    return max_count, best_sequence

max_count, best_sequence = search_n5()

print(f"Maximum count found: {max_count}")
print(f"Corresponding sequence: {best_sequence}")
